import { test, expect } from '@playwright/test';

test.describe('Sticky Header Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('header should be visible on page load', async ({ page }) => {
    const header = page.getByRole('banner');
    await expect(header).toBeVisible();
  });

  test('header should remain visible when scrolling down', async ({ page }) => {
    const header = page.getByRole('banner');
    await page.mouse.wheel(0, 500); // Scroll down
    await expect(header).toBeVisible();
  });
});
